(2006, 'theme_moove', 'instagram', ''),
(2007, 'theme_moove', 'whatsapp', ''),
(2008, 'theme_moove', 'telegram', ''),
(2009, 'theme_moove', 'marketingheading', 'TEKNIK KOMPUTER DAN JARINGAN'),
(2010, 'theme_moove', 'marketingcontent', 'LEARNING MANAGEMENT SYSTEM'),
(2011, 'theme_moove', 'marketing1icon', '/PPJ.jpeg'),
(2012, 'theme_moove', 'marketing1heading', 'Perencanaan & Pengalamatan Jaringan'),
(2013, 'theme_moove', 'marketing1content', 'Mata pelajaran Perencanaan dan Pengalamatan Jaringan mempelajari cara merancang topologi, memilih perangkat, serta mengatur pengalamatan IP (IPv4/IPv6) secara efisien. Fokus utamanya adalah membangun jaringan yang terstruktur, aman, dan handal sesuai kebutuhan pengguna.'),
(2014, 'theme_moove', 'marketing2icon', '/TJKN.jpeg'),
(2015, 'theme_moove', 'marketing2heading', 'Teknologi Jaringan Kabel dan Nirkabel'),
(2016, 'theme_moove', 'marketing2content', 'Mata pelajaran Teknologi Jaringan Kabel dan Nirkabel berfokus pada kompetensi instalasi, konfigurasi, perawatan, dan perbaikan infrastruktur jaringan komputer, baik menggunakan media fisik (kabel) maupun gelombang radio (nirkabel). Peserta didik mempelajari pemasangan kabel fiber optik/UTP, konfigurasi access point, keamanan jaringan, dan manajemen koneksi internet.'),
(2017, 'theme_moove', 'marketing3icon', '/KJ.jpeg'),
(2018, 'theme_moove', 'marketing3heading', 'Keamanan Jaringan'),
(2019, 'theme_moove', 'marketing3content', 'Mata pelajaran Keamanan Jaringan adalah studi yang mempelajari teknik, kebijakan, dan prosedur untuk melindungi integritas, kerahasiaan, dan ketersediaan data serta infrastruktur jaringan komputer dari akses tidak sah, penyalahgunaan, atau serangan siber. Materi ini fokus pada pencegahan, deteksi, dan mitigasi ancaman.'),
(2020, 'theme_moove', 'marketing4icon', '/PKPJ.jpeg'),
(2021, 'theme_moove', 'marketing4heading', 'Pemasangan dan Konfigurasi Perangkat Jaringan'),
(2022, 'theme_moove', 'marketing4content', 'Pemasangan dan Konfigurasi Perangkat Jaringan (PKPJ) adalah mata pelajaran yang fokus pada keterampilan praktis merancang, memasang, dan mengatur perangkat keras serta perangkat lunak jaringan, seperti switch dan router, untuk membentuk LAN/WLAN yang berfungsi optimal sesuai prosedur kerja.'),
(2023, 'theme_moove', 'numbersfrontpagecontent', ''),
