(7, 3, 0, 'PERENCANAAN & PENGALAMATAN JARINGAN', '', 1, '2,3,4,16,17,18,23', 1, NULL, 1779196389),
(8, 3, 1, 'PERTEMUAN 1', '', 1, '5,6,7', 1, NULL, 1774694091),
(9, 3, 3, 'PERTEMUAN 3', '', 1, '11,12', 1, NULL, 1774696735),
(10, 3, 4, 'PERTEMUAN 4', '', 1, '13,14,15', 1, NULL, 1774697366),
(13, 3, 2, 'PERTEMUAN 2', '', 1, '8,9,10,19,21', 1, NULL, 1774696278),
(16, 1, 1, '', '<div style=\"background: linear-gradient(135deg, #141e30, #243b55); border-radius: 15px; padding: 50px 20px; text-align: center; color: white; box-shadow: 0 10px 25px rgba(0,0,0,0.2); font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif; position: relative; overflow: hidden;\">\r\n    \r\n    <img src=\"@@PLUGINFILE@@/Gemini_Generated_Image_3itx5s3itx5s3itx.png\" alt=\"Logo\" style=\"width: 140px; height: 140px; border-radius: 50%; border: 5px solid rgba(255,255,255,0.2); box-shadow: 0 5px 15px rgba(0,0,0,0.5); margin-bottom: 25px; background-color: #ffffff; object-fit: contain; padding: 10px;\">\r\n\r\n    <h1 style=\"margin: 0 0 15px 0; font-size: 38px; font-weight: 800; letter-spacing: 1px; text-shadow: 2px 2px 4px rgba(0,0,0,0.5);\">Selamat Datang di E-Learning</h1>\r\n    <p style=\"font-size: 18px; margin: 0 auto 30px auto; max-width: 650px; line-height: 1.6; color: #d3d9df;\">Tingkatkan pengetahuan dan raih prestasimu. Mulai petualangan belajarmu sekarang dengan materi yang interaktif dan menyenangkan.</p>\r\n\r\n    <a href=\"/moodle/my/courses.php\" style=\"display: inline-block; padding: 14px 35px; background: linear-gradient(to right, #00d2ff, #3a7bd5); color: white; text-decoration: none; font-weight: bold; border-radius: 30px; font-size: 16px; transition: 0.3s; box-shadow: 0 4px 15px rgba(0, 210, 255, 0.4);\">MULAI BELAJAR 🚀</a>\r\n</div>\r\n\r\n<div style=\"display: flex; flex-wrap: wrap; justify-content: center; gap: 25px; margin-top: -30px; margin-bottom: 50px; padding: 0 20px; font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif; position: relative; z-index: 10;\">\r\n    \r\n    <div style=\"flex: 1; min-width: 250px; max-width: 320px; background: white; border-radius: 15px; padding: 30px 20px; text-align: center; box-shadow: 0 8px 20px rgba(0,0,0,0.15); border-top: 6px solid #3a7bd5;\">\r\n        <div style=\"font-size: 45px; margin-bottom: 15px;\">📚</div>\r\n        <h3 style=\"margin-top: 0; color: #2c3e50; font-size: 22px; font-weight: 700;\">Materi Lengkap</h3>\r\n        <p style=\"color: #7f8c8d; font-size: 15px; line-height: 1.5; margin-bottom: 0;\">Akses berbagai modul, bahan tayang, dan video pembelajaran kapan saja.</p>\r\n    </div>\r\n\r\n    <div style=\"flex: 1; min-width: 250px; max-width: 320px; background: white; border-radius: 15px; padding: 30px 20px; text-align: center; box-shadow: 0 8px 20px rgba(0,0,0,0.15); border-top: 6px solid #00d2ff;\">\r\n        <div style=\"font-size: 45px; margin-bottom: 15px;\">✍️</div>\r\n        <h3 style=\"margin-top: 0; color: #2c3e50; font-size: 22px; font-weight: 700;\">Tugas &amp; Kuis</h3>\r\n        <p style=\"color: #7f8c8d; font-size: 15px; line-height: 1.5; margin-bottom: 0;\">Uji pemahamanmu melalui kuis interaktif dan penugasan terstruktur.</p>\r\n    </div>\r\n\r\n    <div style=\"flex: 1; min-width: 250px; max-width: 320px; background: white; border-radius: 15px; padding: 30px 20px; text-align: center; box-shadow: 0 8px 20px rgba(0,0,0,0.15); border-top: 6px solid #28a745;\">\r\n        <div style=\"font-size: 45px; margin-bottom: 15px;\">💬</div>\r\n        <h3 style=\"margin-top: 0; color: #2c3e50; font-size: 22px; font-weight: 700;\">Forum Diskusi</h3>\r\n        <p style=\"color: #7f8c8d; font-size: 15px; line-height: 1.5; margin-bottom: 0;\">Ruang interaksi aktif untuk berdiskusi dengan pengajar dan rekan lainnya.</p>\r\n    </div>\r\n</div>\r\n\r\n<div style=\"height: 60px; width: 100%; clear: both;\"></div>', 1, '22', 1, '{\"op\":\"&\",\"c\":[],\"showc\":[]}', 1778643510),
(17, 1, 0, NULL, '', 1, '20', 1, NULL, 1778042186);
