(2079, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1825, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketingcontent\",\"oldvalue\":\"Moove is a Moodle template based on Boost with modern and creative design.\",\"value\":\"LEARNING MANAGEMENT SYSTEM\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2080, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1826, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing1heading\",\"oldvalue\":\"Lorem\",\"value\":\"Perencanaan & Pengalamatan Jaringan\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2081, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1827, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing1content\",\"oldvalue\":\"Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod.\",\"value\":\"Mata pelajaran Perencanaan dan Pengalamatan Jaringan mempelajari cara merancang topologi, memilih perangkat, serta mengatur pengalamatan IP (IPv4\\/IPv6) secara efisien. Fokus utamanya adalah membangun jaringan yang terstruktur, aman, dan handal sesuai kebutuhan pengguna.\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2082, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1828, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing2heading\",\"oldvalue\":\"Lorem\",\"value\":\"Teknologi Jaringan Kabel dan Nirkabel\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2083, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1829, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing2content\",\"oldvalue\":\"Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod.\",\"value\":\"Mata pelajaran Teknologi Jaringan Kabel dan Nirkabel berfokus pada kompetensi instalasi, konfigurasi, perawatan, dan perbaikan infrastruktur jaringan komputer, baik menggunakan media fisik (kabel) maupun gelombang radio (nirkabel). Peserta didik mempelajari pemasangan kabel fiber optik\\/UTP, konfigurasi access point, keamanan jaringan, dan manajemen koneksi internet.\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2084, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1830, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing3heading\",\"oldvalue\":\"Lorem\",\"value\":\"Keamanan Jaringan\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2085, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1831, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing3content\",\"oldvalue\":\"Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod.\",\"value\":\"Mata pelajaran Keamanan Jaringan adalah studi yang mempelajari teknik, kebijakan, dan prosedur untuk melindungi integritas, kerahasiaan, dan ketersediaan data serta infrastruktur jaringan komputer dari akses tidak sah, penyalahgunaan, atau serangan siber. Materi ini fokus pada pencegahan, deteksi, dan mitigasi ancaman.\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2086, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1832, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing4heading\",\"oldvalue\":\"Lorem\",\"value\":\"Pemasangan dan Konfigurasi Perangkat Jaringan\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2087, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1833, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"marketing4content\",\"oldvalue\":\"Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod.\",\"value\":\"Pemasangan dan Konfigurasi Perangkat Jaringan (PKPJ) adalah mata pelajaran yang fokus pada keterampilan praktis merancang, memasang, dan mengatur perangkat keras serta perangkat lunak jaringan, seperti switch dan router, untuk membentuk LAN\\/WLAN yang berfungsi optimal sesuai prosedur kerja.\",\"plugin\":\"theme_moove\"}', 1778602724, 'web', '0:0:0:0:0:0:0:1', NULL),
(2088, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1834, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"logo\",\"oldvalue\":\"\\/Gemini_Generated_Image_lrpy29lrpy29lrpy (2).png\",\"value\":\"\\/Gemini_Generated_Image_3itx5s3itx5s3itx.png\",\"plugin\":\"theme_moove\"}', 1778602759, 'web', '0:0:0:0:0:0:0:1', NULL),
