INSERT INTO `mdl_question` (`id`, `parent`, `name`, `questiontext`, `questiontextformat`, `generalfeedback`, `generalfeedbackformat`, `defaultmark`, `penalty`, `qtype`, `length`, `stamp`, `timecreated`, `timemodified`, `createdby`, `modifiedby`) VALUES
(1, 0, '1', '<p dir=\"ltr\" style=\"text-align: left;\">Penulisan\r\nnotasi /27 pada alamat IP 192.168.10.0/27 dikenal dengan istilah teknis…<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328114632+odzGvP', 1774698392, 1774698392, 3, 3),
(2, 0, '1', '<p dir=\"ltr\" style=\"text-align: left;\">Penulisan\r\nnotasi /27 pada alamat IP 192.168.10.0/27 dikenal dengan istilah teknis…<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328114811+pmhOxC', 1774698491, 1774698491, 3, 3),
(3, 0, '2', '<p dir=\"ltr\" style=\"text-align: left;\">Sebuah\r\ndivisi IT hanya membutuhkan 12 alamat IP untuk komputer <i>server</i> dan\r\nteknisi. <i>Subnet mask</i> (Prefix) paling efisien yang harus dialokasikan\r\nagar tidak banyak IP terbuang adalah…<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328114943+Y1Qp7B', 1774698583, 1774698583, 3, 3),
(4, 0, '3', '<p dir=\"ltr\" style=\"text-align: left;\">Alasan\r\nutama dan paling krusial menggunakan metode VLSM (<i>Variable Length Subnet\r\nMask</i>) dibandingkan FLSM (<i>Fixed</i>) dalam perancangan jaringan skala\r\nbesar adalah…<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328115052+KgRsFD', 1774698652, 1774698652, 3, 3),
(5, 0, '4', '<p dir=\"ltr\" style=\"text-align: left;\">Jika\r\nsebuah jaringan memiliki blok IP 172.16.0.0/25, berapakah jumlah maksimal PC (<i>host</i>\r\nvalid) yang dapat terhubung ke jaringan tersebut?<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328115314+fonNec', 1774698794, 1774698794, 3, 3),
(6, 0, '4', '<p dir=\"ltr\" style=\"text-align: left;\">Jika\r\nsebuah jaringan memiliki blok IP 172.16.0.0/25, berapakah jumlah maksimal PC (<i>host</i>\r\nvalid) yang dapat terhubung ke jaringan tersebut?<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328115319+drBnIU', 1774698799, 1774698799, 3, 3),
(7, 0, '5', '<p dir=\"ltr\" style=\"text-align: left;\">Dalam\r\nperhitungan subnetting blok IP 192.168.1.0/26, alamat <i>Broadcast</i> untuk\r\nblok <i>subnet</i> pertama adalah…<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328115504+ALQJmd', 1774698904, 1774698904, 3, 3),
(8, 0, '6', 'Nilai\r\n<i>subnet mask</i> dalam format desimal untuk <i>prefix</i> /29 adalah...', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328115620+flTiHr', 1774698980, 1774698980, 3, 3),
(9, 0, '7', '<p dir=\"ltr\" style=\"text-align: left;\">Rentang\r\nIP valid (<i>valid host range</i>) yang dapat dipasang pada komputer klien\r\nuntuk blok <i>network</i> 192.168.10.0/24 adalah...<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328115732+GGGKgX', 1774699052, 1774699052, 3, 3),
(10, 0, '8', '<p dir=\"ltr\" style=\"text-align: left;\">Saat\r\nmelakukan perancangan jaringan menggunakan metode VLSM, langkah pertama yang\r\npaling benar dalam mengalokasikan blok IP ke beberapa divisi adalah mengurutkan\r\nkebutuhan berdasarkan...<br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328115930+vePBky', 1774699170, 1774699170, 3, 3),
(11, 0, '9', '<span style=\"font-size: 0.9375rem;\">Rumus matematika yang digunakan untuk mencari\r\n     jumlah IP </span><i style=\"font-size: 0.9375rem;\">host</i><span style=\"font-size: 0.9375rem;\"> valid dalam suatu </span><i style=\"font-size: 0.9375rem;\">subnet</i><span style=\"font-size: 0.9375rem;\"> adalah... (dimana h adalah sisa bit </span><i style=\"font-size: 0.9375rem;\">host</i><span style=\"font-size: 0.9375rem;\"> / angka nol pada biner).</span><ul type=\"disc\">\r\n</ul>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328120101+SWCRWg', 1774699261, 1774699261, 3, 3),
(12, 0, '10', '<p dir=\"ltr\" style=\"text-align: left;\">Sebuah\r\nPC klien dikonfigurasi dengan IP Address 10.10.10.50/29. Berapakah alamat <i>Network\r\nID</i> dari PC tersebut? <i>(Petunjuk: cari kelipatan blok IP)</i><br></p>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+260328120219+LM0DfQ', 1774699339, 1774699339, 3, 3);
