INSERT INTO `mdl_question_attempts` (`id`, `questionusageid`, `slot`, `behaviour`, `questionid`, `variant`, `maxmark`, `minfraction`, `maxfraction`, `flagged`, `questionsummary`, `rightanswer`, `responsesummary`, `timemodified`) VALUES
(31, 4, 1, 'deferredfeedback', 2, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Penulisan notasi /27 pada alamat IP 192.168.10.0/27 dikenal dengan istilah teknis…\n\n: DHCP\n\n; CIDR\n; DNS\n; NAT\n; MAC Address\n', 'CIDR\n', 'DHCP\n\n', 1778142455),
(32, 4, 2, 'deferredfeedback', 3, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Sebuah divisi IT hanya membutuhkan 12 alamat IP untuk komputer _server_ dan teknisi. _Subnet mask_ (Prefix) paling efisien yang harus dialokasikan agar tidak banyak IP terbuang adalah…\n\n: /24\n; /26\n\n; /27\n\n; /28\n\n; /30\n\n', '/28\n\n', '/26\n\n', 1778142455),
(33, 4, 3, 'deferredfeedback', 4, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Alasan utama dan paling krusial menggunakan metode VLSM (_Variable Length Subnet Mask_) dibandingkan FLSM (_Fixed_) dalam perancangan jaringan skala besar adalah…\n\n: Mencegah pemborosan alamat IP yang tersedia.\n\n; Mempercepat koneksi internet pengguna.\n\n; Mencegah masuknya virus atau _malware_ ke jaringan.\n\n; Mengurangi penggunaan kabel fisik.\n\n; Membuat perangkat _router_ bekerja lebih santai.\n\n', 'Mencegah pemborosan alamat IP yang tersedia.\n\n', 'Mencegah masuknya virus atau _malware_ ke jaringan.\n\n', 1778142455),
(34, 4, 4, 'deferredfeedback', 6, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Jika sebuah jaringan memiliki blok IP 172.16.0.0/25, berapakah jumlah maksimal PC (_host_ valid) yang dapat terhubung ke jaringan tersebut?\n\n: 62 host\n\n; 126 host\n\n; 128 host\n\n; 254 host\n\n; 256 host\n\n', '62 host\n\n', '128 host\n\n', 1778142455),
(35, 4, 5, 'deferredfeedback', 7, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Dalam perhitungan subnetting blok IP 192.168.1.0/26, alamat _Broadcast_ untuk blok _subnet_ pertama adalah…\n\n: 192.168.1.31\n\n; 192.168.1.62\n\n; 192.168.1.63\n\n; 192.168.1.64\n\n; 192.168.1.127', '192.168.1.63\n\n', '192.168.1.64\n\n', 1778142455),
(36, 4, 6, 'deferredfeedback', 8, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Nilai _subnet mask_ dalam format desimal untuk _prefix_ /29 adalah...: 255.255.255.224\n\n; 255.255.255.240\n\n; 255.255.255.248\n\n; 255.255.255.252\n\n; 255.255.255.254\n\n', '255.255.255.248\n\n', '255.255.255.254\n\n', 1778142455),
(37, 4, 7, 'deferredfeedback', 9, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Rentang IP valid (_valid host range_) yang dapat dipasang pada komputer klien untuk blok _network_ 192.168.10.0/24 adalah...\n\n: 192.168.10.0 sampai 192.168.10.255\n\n; 192.168.10.1 sampai 192.168.10.254\n\n; 192.168.10.1 sampai 192.168.10.255\n\n; 192.168.10.0 sampai 192.168.10.254\n\n; 192.168.10.2 sampai 192.168.10.254', '192.168.10.1 sampai 192.168.10.254\n\n', '192.168.10.0 sampai 192.168.10.255\n\n', 1778142455),
(38, 4, 8, 'deferredfeedback', 10, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Saat melakukan perancangan jaringan menggunakan metode VLSM, langkah pertama yang paling benar dalam mengalokasikan blok IP ke beberapa divisi adalah mengurutkan kebutuhan berdasarkan...\n\n: Divisi dengan nama sesuai abjad\n\n; Divisi dengan jumlah _host_ terkecil ke terbesar\n\n; Divisi dengan jumlah _host_ terbesar ke terkecil\n\n; Kecepatan _bandwidth_ yang dibutuhkan divisi\n\n; Letak lantai fisik divisi tersebut berada\n\n', 'Divisi dengan jumlah _host_ terbesar ke terkecil\n\n', 'Divisi dengan jumlah _host_ terkecil ke terbesar\n\n', 1778142455),
(39, 4, 9, 'deferredfeedback', 11, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Rumus matematika yang digunakan untuk mencari jumlah IP _host_ valid dalam suatu _subnet_ adalah... (dimana h adalah sisa bit _host_ / angka nol pada biner).\n\n: 2^h\n\n; 2^h - 1\n\n; 2^h - 2\n\n; 2^h + 2\n\n; 2^h / 2\n\n', '2^h - 2\n\n', '2^h + 2\n\n', 1778142455),
(40, 4, 10, 'deferredfeedback', 12, 1, 1.0000000, 0.0000000, 1.0000000, 0, 'Sebuah PC klien dikonfigurasi dengan IP Address 10.10.10.50/29. Berapakah alamat _Network ID_ dari PC tersebut? _(Petunjuk: cari kelipatan blok IP)_\n\n: 10.10.10.0\n\n; 10.10.10.40\n\n; 10.10.10.48\n\n; 10.10.10.55\n\n; 10.10.10.56\n\n', '10.10.10.48\n\n', '10.10.10.55\n\n', 1778142455);
