(1, 3, 'MODUL AJAR 1', '', 1, 0, 0, NULL, 5, 'a:0:{}', 0, 1, 1774694499),
(2, 3, 'MODUL AJAR 2', '', 1, 0, 0, NULL, 5, 'a:0:{}', 0, 1, 1774696332),
